INSERT INTO app_config(id,app_name,super_admin_emails,system_settings) VALUES('default','OdontoControl AI','[]','{}') ON CONFLICT(id) DO NOTHING;
CREATE TRIGGER IF NOT EXISTS native_orcamento_approved_lock BEFORE UPDATE ON orcamento WHEN OLD.status='aprovado' AND (NEW.status!=OLD.status OR NEW.itens IS NOT OLD.itens OR NEW.total_com_desconto IS NOT OLD.total_com_desconto OR NEW.paciente_id!=OLD.paciente_id OR NEW.parcelas!=OLD.parcelas) BEGIN SELECT RAISE(ABORT,'Orçamento aprovado: preserve os valores; ajuste o financeiro separadamente'); END;
CREATE TRIGGER IF NOT EXISTS native_orcamento_approve AFTER UPDATE OF status ON orcamento WHEN NEW.status='aprovado' AND OLD.status!='aprovado' BEGIN
 INSERT INTO tratamento(id,clinica_id,paciente_id,paciente_nome,profissional_id,descricao,status,data_inicio,valor_total) VALUES('orcamento:'||NEW.id,NEW.clinica_id,NEW.paciente_id,NEW.paciente_nome,NEW.profissional_id,'Orçamento '||coalesce(NEW.numero,NEW.id),'planejado',date('now'),NEW.total_com_desconto);
 INSERT INTO financeiro(id,clinica_id,paciente_id,orcamento_id,tipo,status,descricao,valor,data,categoria,total_parcelas,parcela_atual) VALUES('orcamento:'||NEW.id,NEW.clinica_id,NEW.paciente_id,NEW.id,'receita','pendente','Orçamento '||coalesce(NEW.numero,NEW.id),NEW.total_com_desconto,date('now'),'Tratamento',NEW.parcelas,1);
END;
CREATE TRIGGER IF NOT EXISTS native_orcamento_insert_pending BEFORE INSERT ON orcamento WHEN NEW.status='aprovado' BEGIN SELECT RAISE(ABORT,'Salve o orçamento antes de aprovar'); END;
CREATE TRIGGER IF NOT EXISTS native_orcamento_delete_lock BEFORE DELETE ON orcamento WHEN OLD.status='aprovado' BEGIN SELECT RAISE(ABORT,'Orçamento aprovado possui financeiro e tratamento vinculados'); END;
