CREATE TRIGGER IF NOT EXISTS native_consulta_no_overlap_INSERT BEFORE INSERT ON consulta WHEN NEW.status NOT IN ('cancelada','faltou') AND EXISTS(SELECT 1 FROM consulta c WHERE c.id!=NEW.id AND c.clinica_id=NEW.clinica_id AND c.profissional_id=NEW.profissional_id AND c.data=NEW.data AND c.status NOT IN ('cancelada','faltou') AND (CAST(substr(c.hora,1,2) AS INTEGER)*60+CAST(substr(c.hora,4,2) AS INTEGER))<(CAST(substr(NEW.hora,1,2) AS INTEGER)*60+CAST(substr(NEW.hora,4,2) AS INTEGER))+NEW.duracao_minutos AND (CAST(substr(c.hora,1,2) AS INTEGER)*60+CAST(substr(c.hora,4,2) AS INTEGER))+c.duracao_minutos>(CAST(substr(NEW.hora,1,2) AS INTEGER)*60+CAST(substr(NEW.hora,4,2) AS INTEGER))) BEGIN SELECT RAISE(ABORT,'Horário indisponível para este profissional'); END;
CREATE TRIGGER IF NOT EXISTS native_consulta_no_overlap_UPDATE BEFORE UPDATE ON consulta WHEN NEW.status NOT IN ('cancelada','faltou') AND EXISTS(SELECT 1 FROM consulta c WHERE c.id!=NEW.id AND c.clinica_id=NEW.clinica_id AND c.profissional_id=NEW.profissional_id AND c.data=NEW.data AND c.status NOT IN ('cancelada','faltou') AND (CAST(substr(c.hora,1,2) AS INTEGER)*60+CAST(substr(c.hora,4,2) AS INTEGER))<(CAST(substr(NEW.hora,1,2) AS INTEGER)*60+CAST(substr(NEW.hora,4,2) AS INTEGER))+NEW.duracao_minutos AND (CAST(substr(c.hora,1,2) AS INTEGER)*60+CAST(substr(c.hora,4,2) AS INTEGER))+c.duracao_minutos>(CAST(substr(NEW.hora,1,2) AS INTEGER)*60+CAST(substr(NEW.hora,4,2) AS INTEGER))) BEGIN SELECT RAISE(ABORT,'Horário indisponível para este profissional'); END;
CREATE TRIGGER IF NOT EXISTS odontocontrol_schema_v1 BEFORE UPDATE ON template_owner BEGIN SELECT RAISE(ABORT,'Proprietário protegido'); END;
